import re

from taf.ul.bts_components.core.device import Device
from ..pylogger.logger import log_input_and_output, log_operation, log_result
from .exceptions import WrongActivationStatus, BBMODInformationNotFound


class Bbmod(Device):

    def __init__(self):
        super(Bbmod, self).__init__()

    @log_input_and_output
    def connect_to(self, address, username, password, proxy=None, alias=None):
        """
        Connects to baseband module via ssh.

        :param address: Address to capacity unit.
        :type address: str
        :param username: Username that should be used in authentication.
        :type username: str
        :param password: Password that will be used in authentication and to try to decrypt the
            private key if needed.
        :type password: str
        :param proxy: Opened connection to the remote host, from which the new
            connection will be started.
        :type proxy: Connection, optional
        :param alias: Name of device; if None provided then default alias will be used
        :type alias: str or None
        """
        self._connect_to(
            hostname=address, username=username, password=password, proxy=proxy, alias=alias
        )

    @log_input_and_output
    def get_cpri_link_status(self, reg_address="0xDF201004"):
        """
        Gets cpri link status of baseband module with provided ip address.

        :param reg_address: registry address on capacity unit to check cpri link status, `0xDF201004` at default.
        :type reg_address: str

        :return: cpri link status from particular capacity unit
        :rtype: str
        """
        log_operation("Reading CPRI status.")

        cpri_status = self.execute(command="fpga_rw ra {0}".format(reg_address))

        log_result("Read CPRI status: {}".format(cpri_status))

        return cpri_status.strip()

    @log_input_and_output
    def validate_cpri_link_activation_status(self, cpri_status):
        """
        Validates CPRI link activation statuses of all detected baseband modules by comparing with correct
        activation status ('0x00000010').

        :param cpri_status: cpri link status from particular baseband module
        :type cpri_status: str
        :raises: WrongActivationStatus exception if any of baseband module has status different than
                 activation status.
        """
        if not self.is_cpri_link_activated_on_bbmod(cpri_status):
            raise WrongActivationStatus("CPRI link on baseband module with alias {0} is not activated!".
                                        format(self.get_alias()))

    @log_input_and_output
    def is_cpri_link_activated_on_bbmod(self, cpri_status):
        """
        Checks if cpri link status is equal to activation status on provided capacity unit.

        :param cpri_status: Cpri link status to be checked
        :type cpri_status: str
        :return: True if activation status is present on capacity unit, False otherwise.
        """
        cpri_active_val = '0x00000010'

        if cpri_status != cpri_active_val:
            log_result("Baseband module does not have CPRI link activated status \n"
                       "  Activation status = {0}, \n"
                       "  Current value = {1}.".format(cpri_active_val, cpri_status))
            return False

        return True

    @log_input_and_output
    def get_bbmod_serial_number(self):
        """
        Gets serial number of particular baseband module, based on 'chk sysversions' command output performed on BBMOD
        or file "serial-number" content, depending on BBMOD's chk command support.

        :return: serial number read from particular capacity unit
        :rtype: str

        :raises: BBMODInformationNotFound exception if baseband module serial number was not found in chk command output
                 or in 'serial-number' file.
        """
        log_operation("Reading BBMOD serial number.")

        chk_command = "chk sysversions"
        command_output = self.execute(command=chk_command)

        return self._get_bbmod_serial_number_without_chk() if "command not found" in command_output \
            else self._get_bbmod_serial_number_with_chk(chk_command, command_output)

    @log_input_and_output
    def _get_bbmod_serial_number_with_chk(self, chk_command, chk_command_output):
        """Method used for BBMODs with 'chk' command, example for ABIP, ABIQ or ABIN module."""
        for line in str(chk_command_output).split("\r"):
            if "module serial-number" in line:
                return line.split("module serial-number = ")[-1].split(" ")[0]

        raise BBMODInformationNotFound("Baseband module serial number is not found in '{}' command output: {}".
                                       format(chk_command, chk_command_output))

    @log_input_and_output
    def _get_bbmod_serial_number_without_chk(self):
        """Method used for BBMODs without 'chk' command, example for ABIA module."""
        serial_number_file_path = "/sys/firmware/devicetree/base/module-identity/serial-number"
        command_output = self.execute(command="cat {}".format(serial_number_file_path))
        matched_serial = re.search(r"[A-Z]*[0-9]*", command_output).group()

        if matched_serial:
            return matched_serial

        raise BBMODInformationNotFound("Baseband module serial number is not found in '{}' file. "
                                       "Cat command output: {}".format(serial_number_file_path, command_output))
